import { Activity, Languages, Monitor, Moon, Sun } from "lucide-react";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import type { ThemeMode } from "../context/preferences-context";
import { usePreferences } from "../hooks/usePreferences";

const themeOptions: Array<{ mode: ThemeMode; icon: typeof Sun; labelKey: string }> = [
  { mode: "light", icon: Sun, labelKey: "settings.light" },
  { mode: "dark", icon: Moon, labelKey: "settings.dark" },
  { mode: "system", icon: Monitor, labelKey: "settings.system" },
];

export function SettingsControls() {
  const { t } = useTranslation();
  const { themeMode, language, motionEnabled, setLanguage, setMotionEnabled, setThemeMode } = usePreferences();
  const [feedback, setFeedback] = useState("");

  useEffect(() => {
    if (!feedback) return;
    const timer = window.setTimeout(() => setFeedback(""), 1500);
    return () => window.clearTimeout(timer);
  }, [feedback]);

  const chooseTheme = (mode: ThemeMode) => {
    setThemeMode(mode);
    const option = themeOptions.find((item) => item.mode === mode);
    if (option) setFeedback(t(option.labelKey));
  };

  return (
    <div className="settings-controls">
      <div className="segmented-control theme-control" role="group" aria-label={t("settings.theme")}>
        {themeOptions.map(({ mode, icon: Icon, labelKey }) => (
          <button
            className={themeMode === mode ? "active" : ""}
            type="button"
            key={mode}
            onClick={() => chooseTheme(mode)}
            aria-label={t(labelKey)}
            aria-pressed={themeMode === mode}
            title={t(labelKey)}
          >
            <Icon size={14} />
          </button>
        ))}
      </div>
      <div className="segmented-control language-control" role="group" aria-label={t("settings.language")}>
        <Languages size={13} aria-hidden="true" />
        {(["zh-CN", "en"] as const).map((item) => (
          <button
            className={language === item ? "active" : ""}
            type="button"
            key={item}
            onClick={() => { setLanguage(item); setFeedback(item === "zh-CN" ? "简体中文" : "English"); }}
            aria-pressed={language === item}
            title={item === "zh-CN" ? t("settings.zh") : t("settings.en")}
          >
            {item === "zh-CN" ? "中" : "EN"}
          </button>
        ))}
      </div>
      <button
        className={`icon-button motion-toggle ${motionEnabled ? "active" : ""}`}
        type="button"
        onClick={() => {
          setMotionEnabled(!motionEnabled);
          setFeedback(t(motionEnabled ? "settings.motionDisabled" : "settings.motionEnabled"));
        }}
        aria-label={t(motionEnabled ? "settings.motionOn" : "settings.motionOff")}
        aria-pressed={motionEnabled}
        title={t(motionEnabled ? "settings.motionOn" : "settings.motionOff")}
      >
        <Activity size={16} />
      </button>
      <span className={`settings-feedback ${feedback ? "visible" : ""}`} role="status" aria-live="polite">{feedback}</span>
    </div>
  );
}
